import pathlib,json,statistics
b=pathlib.Path(__file__).parent;rows=[json.loads(p.read_text()) for p in sorted(b.glob('cellular-*-summary.json'))]
excluded={'cellular-after-r1-12000k'}
comparative=[r for r in rows if r['size']=='720x1600' and r['mode']=='VBR' and 'complex' not in r['label'] and 'before' not in r['label'] and r['label'] not in excluded]
lines=['# 移动数据串流测试及云端资源优化','', '日期：2026-09-29。测试手机为已USB授权的一加15（Android16），目标使用手机仍为火锅的真我V50。所有cellular样本逐批核对默认网络为MOBILE/NR、WiFi关闭；地址为146.56.249.175:15556。只有一个lan样本作为源端能力对照。','',f'完成 {len(rows)} 组移动数据样本，另有1组局域网对照。除高细节专项为25秒外，一般每组30秒。均使用手机实际硬件AVC解码器c2.qti.avc.decoder.low_latency，所有样本结束时串流仍连接；这不代表中途没有停顿。','', '普通动态画面与复杂画面分开记录。普通画面为持续运动条纹与圆形，复杂画面增加固定噪声纹理的连续平移，不是实际短视频App兼容性验收。显示FPS由MediaCodec OnFrameRenderedListener回调统计，均值舍去前3秒；长帧间隔按整个样本统计。ms是TLS建立后的HTTP/ping往返，**不是触摸到画面响应的端到端延迟**。','', '## 普通画面码率比较','', '均为720×1600、VBR、60FPS上限、120ms缓冲。2.5/6Mbps各3次、4/8Mbps各6次、12Mbps至少3次。测试跨多个时间和资源调整阶段，移动网络不是受控信道，**不能依据均值排序认定某一码率因果上更流畅**。', '', '|目标 Mbps|有效次数|平均呈现 FPS|各次均值范围|最长画面间隔 ms|>100ms间隔总次数|平均总接收 Mbps|','|---|---:|---:|---|---:|---:|---:|']
for rate in [2500000,4000000,6000000,8000000,12000000]:
 x=[r for r in comparative if r['requested_bps']==rate];v=[r['render_fps_mean'] for r in x]
 lines.append(f'|{rate/1e6:g}|{len(x)}|{statistics.mean(v):.2f}|{min(v):.2f}–{max(v):.2f}|{max(r["render_gap_max_ms"] for r in x):.2f}|{sum(r["render_gaps_over_100ms"] for r in x)}|{statistics.mean(r["received_total_mbps"] for r in x):.2f}|')
lines+=['','cellular-after-r1-12000k与短时strace诊断在时间上重合，仅归档、不用于上表比较；以cellular-final-12000k补齐12Mbps无干扰样本。软件编码器收到的设置为目标值，不是精确的输出限制。','', '## V50预设与复杂画面','', '|样本|模式/目标Mbps|尺寸/帧率上限|平均呈现FPS|最长间隔ms|总接收Mbps|视频包体接收Mbps|','|---|---|---|---:|---:|---:|---:|']
for r in rows:
 if 'v50' in r['label'] or 'complex' in r['label']:
  v=r.get('received_video_mbps');lines.append(f'|{r["label"]}|{r["mode"]}/{r["requested_bps"]/1e6:g}|{r["size"]}/{r["fps_limit"]}|{r["render_fps_mean"]:.2f}|{r["render_gap_max_ms"]:.2f}|{r["received_total_mbps"]:.2f}|{v:.2f}|' if v is not None else f'|{r["label"]}|{r["mode"]}/{r["requested_bps"]/1e6:g}|{r["size"]}/{r["fps_limit"]}|{r["render_fps_mean"]:.2f}|{r["render_gap_max_ms"]:.2f}|{r["received_total_mbps"]:.2f}|未单独计数|')
lan=json.loads((b/'lan-complex-vbr4-control-summary.json').read_text());lines+=['',f'唯一LAN复杂画面对照：720P/VBR目标4Mbps，实际视频包体{lan["received_video_mbps"]:.2f}Mbps，呈现{lan["render_fps_mean"]:.2f}FPS，最长间隔{lan["render_gap_max_ms"]:.2f}ms，>100ms间隔0次。源端在该画面下未达到稳定60FPS，公网还增加长间隔。','', '## 已执行优化和判断','', '云服务器原有NPS与一个运行约10天的文件扫描Python脚本分别占约一个CPU核心。已对扫描脚本所在、仅含其与父bash的会话设置10%单核心CPU额度，保留未知用途进程；NPS Nice=-5、CPUWeight=1000持久化。短时pprof仅127.0.0.1启用、采样后恢复原配置并关闭。重启后串流时NPS短时采样约11.4–25.3%单核心，整体CPU样本约26.2%忙；与优化前接近全忙相比，计算余量明显增加。不能把短时结果承诺为长期固定CPU。','', '原有BBR/fq、无重复压缩及不限速设置已核对并保留，其他监控/安全/业务组件没有删除。详细回滚在CLOUD-CHANGES.md。','', '高细节画面下，CBR目标4Mbps的视频包体接收约16.55Mbps；VBR目标4Mbps约13.66Mbps。设备CCodec日志确认源端c2.android.avc.encoder，VBR目标4M、frame-rate60进入实际配置。仍不能将配置受理与输出严格符合目标混同。接收值受交付和缓冲影响，不等同于源端瞬时产生码率；总接收来自TrafficStats UID并含音频/协议/已到内核但尚未解析的视频，不能当作纯视频。','', '资源释放解决了CPU竞争；移动网络仍有长帧间隔。本轮不能宣布“外网非常流畅”完成，也不能认为8/12Mbps始终好于低码率。下一阶段应在保持Root/应用数据与国内NPS物理直出边界下，分别验证有可测码率控制的源端编码和P2P/UDP媒体路径，不把QUIC可靠字节流自动等同于无等待视频传输。V50预设为540P/VBR目标2.5M/30FPS/120ms，属于保守起点，实际V50仍需长期验证。','', 'v1.14新增实际视频包体接收Mbps及目标值，保留V50默认、30/60FPS选择和指标一键隐藏。公网与LAN下载、哈希、版本清单已核验；本轮更新没有接入P2P/QUIC，也没有修复虚拟机内快手绿色视频/抖音极速版启动问题。','', '## 逐次数据','', '|标签|模式/目标Mbps|均值FPS|HTTP往返均值ms|最长间隔ms|>100ms数|','|---|---|---:|---:|---:|---:|']
for r in rows:lines.append(f'|{r["label"]}|{r["mode"]}/{r["requested_bps"]/1e6:g}|{r["render_fps_mean"]:.2f}|{r["rtt_ms_mean"]:.2f}|{r["render_gap_max_ms"]:.2f}|{r["render_gaps_over_100ms"]}|')
(b/'CELLULAR-REPORT.md').write_text('\n'.join(lines)+'\n');(b/'cellular-all-summary.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2));print('Report written',len(rows),'mobile samples')
